package com.pp.shaderlod.lod.terrain;import com.mojang.brigadier.CommandDispatcher;import com.mojang.brigadier.arguments.IntegerArgumentType;
public final class GeometryLodCommands{public static void register(CommandDispatcher<net.fabricmc.fabric.api.client.command.v2.FabricClientCommandSource> d){d.register(net.fabricmc.fabric.api.client.command.v2.ClientCommands.literal("shaderlod").then(net.fabricmc.fabric.api.client.command.v2.ClientCommands.literal("terrain").then(net.fabricmc.fabric.api.client.command.v2.ClientCommands.literal("confirm").executes(c->{boolean ok=GeometryLodController.confirmCurrentScene();c.getSource().sendFeedback(net.minecraft.network.chat.Component.literal(ok?"DH replacement coverage confirmed for this scene.":GeometryLodController.confirmationReason()));return ok?1:0;})).then(net.fabricmc.fabric.api.client.command.v2.ClientCommands.literal("revoke").executes(c->{GeometryLodController.revokeCurrentScene();return 1;})).then(net.fabricmc.fabric.api.client.command.v2.ClientCommands.literal("cap").then(net.fabricmc.fabric.api.client.command.v2.ClientCommands.argument("chunks",IntegerArgumentType.integer(8,32)).executes(c->{GeometryLodController.setCap(IntegerArgumentType.getInteger(c,"chunks"));return 1;})))));}}
